//! Differential evidence generated by the actual checked-in Go SDK translators.
use super::*;
use crate::modules::codex_native_api::{chat, compat};
use serde_json::{json, Value};

fn fixtures() -> Vec<Value> {
    serde_json::from_str(include_str!("fixtures/parity22_protocol_go.json")).unwrap()
}

fn output_projection(value: &Value) -> Value {
    json!(value
        .as_array()
        .unwrap()
        .iter()
        .map(|item| {
            let mut result = json!({"type":item["type"]});
            for key in ["name", "namespace", "call_id", "arguments", "input"] {
                if let Some(value) = item.get(key) {
                    result[key] = value.clone();
                }
            }
            if item["type"] == "reasoning" || item["type"] == "message" {
                let key = if item["type"] == "reasoning" {
                    "summary"
                } else {
                    "content"
                };
                result["text"] = json!(item[key]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter_map(|p| p["text"].as_str())
                    .collect::<Vec<_>>()
                    .join(""));
            }
            result
        })
        .collect::<Vec<_>>())
}

#[test]
fn parity22_protocol_actual_go_request_and_output_fixtures() {
    let cases = fixtures();
    assert!(cases.len() > 60);
    for case in cases {
        let input = case["input"].clone();
        let actual = match case["kind"].as_str().unwrap() {
            "canonical" => {
                let response = if case["source"] == "chat" {
                    chat::prepare_request(input, chat::ChatFlavor::ChatCompletions)
                        .unwrap()
                        .responses
                } else {
                    let flavor = if case["source"] == "claude" {
                        compat::CompatFlavor::Claude
                    } else {
                        compat::CompatFlavor::Gemini
                    };
                    compat::prepare_request(input, flavor, Some("parity-model"), Some(false))
                        .unwrap()
                        .responses
                };
                let mut projection = json!({});
                for key in case["expected"].as_object().unwrap().keys() {
                    projection[key] = response[key].clone();
                }
                projection
            }
            "responses_chat" => {
                let response = responses_to_chat(&input).unwrap();
                let mut projection = json!({});
                for key in case["expected"].as_object().unwrap().keys() {
                    projection[key] = response[key].clone();
                }
                // Go currently copies flat choice objects verbatim. Retain Rust's
                // legal nested Chat choice extension and assert its wire shape.
                if case["go_tool_choice"].is_object() {
                    assert_eq!(case["go_tool_choice"]["type"], "custom");
                    assert_eq!(
                        response["tool_choice"],
                        json!({"type":"function","function":{"name":"terminal__patch"}})
                    );
                }
                projection
            }
            "ollama_arguments" => {
                let response =
                    compat::prepare_request(input, compat::CompatFlavor::Ollama, None, None)
                        .unwrap()
                        .responses;
                json!(response["input"].as_array().unwrap().iter().filter(|i|i["type"]=="function_call").map(|item|json!({"id":item["call_id"],"type":"function","function":{"name":item["name"],"arguments":item["arguments"]}})).collect::<Vec<_>>())
            }
            "chat_output" => {
                let context = ToolContext::from_responses(&case["request"]);
                let response =
                    chat_to_response_with_context(&input, "parity-model", &context).unwrap();
                output_projection(&response["output"])
            }
            _ => panic!("unknown fixture kind"),
        };
        assert_eq!(
            actual, case["expected"],
            "Go differential case {}",
            case["name"]
        );
    }
}

#[test]
fn parity22_go_outputs_also_match_streamed_reasoning_namespaces_and_custom_wrappers() {
    for case in fixtures()
        .into_iter()
        .filter(|c| c["kind"] == "chat_output")
    {
        let context = ToolContext::from_responses(&case["request"]);
        let mut adapter = ResponsesStreamAdapter::with_context("parity-model".into(), context);
        let mut events = Vec::new();
        for chunk in case["chunks"].as_array().unwrap() {
            events.extend(adapter.push(chunk).unwrap());
        }
        events.extend(adapter.finish_done().unwrap());
        let response = &events.last().unwrap()["response"];
        assert_eq!(
            output_projection(&response["output"]),
            case["expected_stream"],
            "streamed Go fixture {}",
            case["name"]
        );
        if case["name"] == "namespace_custom" {
            let streamed = events
                .iter()
                .filter(|e| e["type"] == "response.custom_tool_call_input.delta")
                .filter_map(|e| e["delta"].as_str())
                .collect::<Vec<_>>()
                .join("");
            assert_eq!(
                streamed,
                case["expected_stream"][0]["input"].as_str().unwrap()
            );
        }
    }
}

#[test]
fn parity22_tool_choices_and_native_custom_extension_remain_consistent() {
    let request = json!({"input":[],"tools":[{"type":"namespace","name":"terminal","tools":[{"type":"custom","name":"patch"},{"type":"function","name":"exec","parameters":{}}]}],"tool_choice":{"type":"allowed_tools","mode":"required","tools":[{"type":"custom","namespace":"terminal","name":"patch"},{"type":"function","namespace":"terminal","name":"exec"}]}});
    let wire = responses_to_chat(&request).unwrap();
    assert_eq!(
        wire["tool_choice"],
        json!({"type":"allowed_tools","allowed_tools":{"mode":"required","tools":[{"type":"function","function":{"name":"terminal__patch"}},{"type":"function","function":{"name":"terminal__exec"}}]}})
    );
    let native = responses_to_native_chat(&request).unwrap();
    assert_eq!(native["tools"][0]["type"], "custom");
    assert_eq!(
        native["tool_choice"]["allowed_tools"]["tools"][0]["type"],
        "custom"
    );
    let strict = responses_to_chat(&json!({"input":[],"tools":[{"type":"function","name":"strict_fn","parameters":{"type":"object"},"strict":true}]})).unwrap();
    assert_eq!(strict["tools"][0]["function"]["strict"], true);
    let default_native = compat::prepare_native_chat(
        &json!({"model":"m","messages":[]}),
        compat::CompatFlavor::Claude,
        None,
        None,
    )
    .unwrap();
    assert!(default_native.body.get("reasoning_effort").is_none());
    let auto_native = compat::prepare_native_chat(
        &json!({"model":"m","messages":[],"thinking":{"type":"enabled"}}),
        compat::CompatFlavor::Claude,
        None,
        None,
    )
    .unwrap();
    assert_eq!(auto_native.body["reasoning_effort"], "auto");
    assert!(responses_to_chat(
        &json!({"input":[{"type":"reasoning","encrypted_content":"opaque-owner"}]})
    )
    .is_err());
    let mut adapter =
        ResponsesStreamAdapter::with_context("m".into(), ToolContext::from_responses(&request));
    adapter.push(&json!({"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"a","function":{"name":"terminal__patch","arguments":"{\"input\":\"partial"}}]},"finish_reason":"tool_calls"}]})).unwrap();
    assert!(adapter.finish_done().is_err());
}

#[test]
fn parity22_custom_wrapper_decodes_unicode_surrogates_without_repeating_prefixes() {
    let mut adapter = ResponsesStreamAdapter::with_context(
        "m".into(),
        ToolContext::from_responses(&json!({"tools":[{"type":"custom","name":"patch"}]})),
    );
    let mut events = Vec::new();
    for fragment in ["{\"input\":\"a", "\\uD83D", "\\uDE00", "\\n", "b\"}"] {
        events.extend(adapter.push(&json!({"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"a","function":{"name":if events.is_empty(){"patch"}else{""},"arguments":fragment}}]},"finish_reason":null}]})).unwrap());
    }
    adapter
        .push(&json!({"choices":[{"index":0,"delta":{},"finish_reason":"tool_calls"}]}))
        .unwrap();
    events.extend(adapter.finish_done().unwrap());
    assert_eq!(
        events
            .iter()
            .filter(|e| e["type"] == "response.custom_tool_call_input.delta")
            .filter_map(|e| e["delta"].as_str())
            .collect::<Vec<_>>()
            .join(""),
        "a😀\nb"
    );
    assert_eq!(
        events.last().unwrap()["response"]["output"][0]["input"],
        "a😀\nb"
    );
}

#[test]
fn parity22_fragmented_names_keep_rust_extension_beyond_go_stream_parser() {
    // Go assumes a whole name chunk. Rust deliberately also supports fragmented
    // names; compare the result with the actual Go nonstream identity fixture.
    for case in fixtures().into_iter().filter(|c| {
        c["kind"] == "chat_output" && c["name"].as_str().unwrap().starts_with("namespace_")
    }) {
        let mut adapter = ResponsesStreamAdapter::with_context(
            "parity-model".into(),
            ToolContext::from_responses(&case["request"]),
        );
        let call = &case["input"]["choices"][0]["message"]["tool_calls"][0];
        let name = call["function"]["name"].as_str().unwrap();
        for part in [&name[..name.len() / 2], &name[name.len() / 2..]] {
            adapter.push(&json!({"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":call["id"],"function":{"name":part,"arguments":""}}]},"finish_reason":null}]})).unwrap();
        }
        adapter.push(&json!({"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":call["function"]["arguments"]}}]},"finish_reason":"tool_calls"}]})).unwrap();
        let events = adapter.finish_done().unwrap();
        assert_eq!(
            output_projection(&events.last().unwrap()["response"]["output"]),
            case["expected"]
        );
    }
}
